//! Store anchors (1.5.0): the reference's anchor checks, against
//! `fixtures/anchors.json` (generated by the Python reference with
//! `scripts/generate_anchor_vectors.py`).

use genesis_mesh_sdk::{
    canonical::anchor_digest,
    json,
    verify::{
        check_anchors, check_events_against_anchors, export_checkpoint, parse_anchors,
        parse_export_lines, verify_evidence_events, verify_store_anchors, VerificationFailure,
        VerifyEvidenceOptions,
    },
    Value,
};

fn suite() -> Value {
    serde_json::from_str(include_str!("fixtures/anchors.json")).unwrap()
}

fn strings(value: &Value) -> Vec<String> {
    value
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_str().unwrap().to_owned())
        .collect()
}

/// An export checked as `genesis-mesh evidence verify-export --known-anchors`
/// checks it, in its JSON form.
fn verify_export_with_anchors(input: &Value) -> Value {
    let events = parse_export_lines(input["lines"].as_str().unwrap()).unwrap();
    let keys = strings(&input["na_public_keys"]);
    let anchors = check_anchors(input["anchors"].as_array().unwrap().clone()).unwrap();
    let options = VerifyEvidenceOptions {
        checkpoint: export_checkpoint(&events),
        ..VerifyEvidenceOptions::new(
            keys.clone(),
            input["executor_keys"].as_array().unwrap().clone(),
        )
    };
    let mut result = verify_evidence_events(&events, &options);
    for f in verify_store_anchors(&anchors, Some(&keys), None).failures {
        result.verified = false;
        result.failures.push(VerificationFailure {
            store_sequence: None,
            reason: f.reason,
            detail: format!("anchor {} {}", f.anchor_sequence.unwrap(), f.detail)
                .trim_end()
                .to_owned(),
        });
    }
    let coverage = check_events_against_anchors(
        &events,
        &anchors,
        &mut result,
        input["partial"] == true,
        input["from_anchor"] == true,
    );
    let mut out = serde_json::to_value(&result).unwrap();
    out["anchors"] = serde_json::to_value(coverage).unwrap();
    out
}

#[test]
fn every_vector_gives_the_reference_outcome() {
    let suite = suite();
    assert_eq!(suite["suite"], "anchors");
    let mut ran = 0;
    for v in suite["vectors"].as_array().unwrap() {
        let input = &v["input"];
        match v["kind"].as_str().unwrap() {
            "verify_anchors" => {
                let anchors = check_anchors(input["anchors"].as_array().unwrap().clone())
                    .unwrap_or_else(|e| panic!("{}: {e}", v["id"]));
                let keys = strings(&input["na_public_keys"]);
                let result =
                    verify_store_anchors(&anchors, Some(&keys), input["sovereign_id"].as_str());
                let mut expected = v["expected"].clone();
                let digests = expected.as_object_mut().unwrap().remove("digests").unwrap();
                assert_eq!(
                    serde_json::to_value(&result).unwrap(),
                    expected,
                    "{}",
                    v["id"]
                );
                let ours: Vec<String> = anchors.iter().map(|a| anchor_digest(a).unwrap()).collect();
                assert_eq!(json!(ours), digests, "{}", v["id"]);
            }
            "verify_export_anchors" => {
                let expected = &v["expected"];
                let out = verify_export_with_anchors(input);
                assert_eq!(out, expected["output"], "{}", v["id"]);
                assert_eq!(
                    expected["exit_code"] == 0,
                    out["verified"] == true,
                    "{}",
                    v["id"]
                );
            }
            other => panic!("unknown vector kind {other}"),
        }
        ran += 1;
    }
    assert_eq!(ran, 18);
}

#[test]
fn signatures_are_skipped_only_when_asked() {
    let suite = suite();
    let other_key = suite["vectors"]
        .as_array()
        .unwrap()
        .iter()
        .find(|v| v["id"] == "chain-other-key")
        .unwrap();
    let anchors = check_anchors(other_key["input"]["anchors"].as_array().unwrap().clone()).unwrap();
    assert!(verify_store_anchors(&anchors, None, None).verified);
    assert!(!verify_store_anchors(&anchors, Some(&[]), None).verified);
}

#[test]
fn held_anchors_read_in_every_form_the_reference_reads() {
    let suite = suite();
    let held = suite["vectors"][0]["input"]["anchors"].clone();
    let lines: Vec<String> = held
        .as_array()
        .unwrap()
        .iter()
        .rev()
        .map(|a| serde_json::to_string(a).unwrap())
        .collect();
    for text in [
        serde_json::to_string(&held).unwrap(),
        serde_json::to_string(&json!({ "anchors": held })).unwrap(),
        format!("\r\n{}\n\n", lines.join("\n")),
    ] {
        let anchors = parse_anchors(&text).unwrap();
        assert_eq!(json!(anchors), held, "ordered by anchor_sequence: {text}");
    }
    let one = parse_anchors(&serde_json::to_string(&held[1]).unwrap()).unwrap();
    assert_eq!(json!(one), json!([held[1]]));
    assert!(parse_anchors("").unwrap().is_empty());
    assert!(parse_anchors("not json").unwrap().is_empty());
    // Not a StoreAnchor: an unknown field, a time not in UTC, position 0, a
    // duplicate key.
    let mut extra = held[0].clone();
    extra["note"] = json!("x");
    let mut naive = held[0].clone();
    naive["anchored_at"] = json!("2026-10-01T10:01:00");
    let mut zero = held[0].clone();
    zero["anchor_sequence"] = json!(0);
    for bad in [extra, naive, zero] {
        assert!(parse_anchors(&bad.to_string()).is_err(), "{bad}");
    }
    assert!(parse_anchors(r#"{"anchors": [], "anchors": []}"#).is_err());
}

#[test]
fn an_export_after_retention_continues_from_the_checkpoint_it_holds() {
    let suite: Value = serde_json::from_str(include_str!("fixtures/out_of_band.json")).unwrap();
    let lines = |id: &str| {
        let v = suite["vectors"]
            .as_array()
            .unwrap()
            .iter()
            .find(|v| v["id"] == id)
            .unwrap();
        parse_export_lines(v["input"]["lines"].as_str().unwrap()).unwrap()
    };
    let after = lines("export-after-two-retention-runs");
    let first = after
        .iter()
        .map(|e| e["entry"]["store_sequence"].as_i64().unwrap())
        .min()
        .unwrap();
    let checkpoint = export_checkpoint(&after).expect("the run starts at its checkpoint");
    assert_eq!(checkpoint["removed_through_sequence"], first - 1);
    assert_eq!(export_checkpoint(&lines("export-valid")), None);
    assert_eq!(export_checkpoint(&[]), None);
}
